command:
set -e
case "$(uname -m)" in
  x86_64)  arch=amd64; sum=c5b0666b4cb676901f90dfcb37106783c5fe2077b04590973b885950611b30ee ;;
  aarch64) arch=arm64; sum=eae1d3aa50c48fb23b8cbdf4e369d0910dfc538566bfd09df89a774aa84a48b9 ;;
  *) echo "no tini-static for $(uname -m)"; exit 1 ;;
esac
curl -fsSL -o /tmp/tini "https://github.com/krallin/tini/releases/download/v0.19.0/tini-static-$arch"
echo "$sum  /tmp/tini" | sha256sum -c -
chmod 755 /tmp/tini
